'use strict';
// Opt-in native save-panel acceptance. Uses only disposable generated bytes and
// an isolated session; select the printed temporary destination in the panel.
const { app, BrowserWindow, ipcMain, dialog } = require('electron');
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const assert = require('node:assert/strict');
const { createHash, randomUUID } = require('node:crypto');
const { DesktopFileExport } = require('../../lib/file-export.cjs');
const { startRendererServer } = require('../../lib/renderer-server.cjs');
const { pathToFileURL } = require('node:url');
const headless = process.argv.includes('--headless');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'tt-file-export-native-'));
app.setName('Thingtime File Export Verification'); app.setPath('userData', path.join(root, 'profile'));
const output = path.join(root, 'saved'); fs.mkdirSync(output, { mode: 0o700 });
const bytes = Buffer.alloc(17 * 1024 * 1024 + 17, 61), digests = [];
for (let at = 0; at < bytes.length; at += 8388608) digests.push(createHash('sha256').update(bytes.subarray(at, at + 8388608)).digest());
const content = { attachmentId: 'retained-version', version: 'd'.repeat(64), size: bytes.length,
    fingerprint: { algorithm: 'sha256-parts-v1', partSizeBytes: 8388608, partCount: digests.length,
        sha256: createHash('sha256').update(Buffer.concat(digests)).digest('hex') } };
let window, server, renderer, origin, apiOrigin, host, ranges = 0, accountReads = 0;
const timer = setTimeout(() => { console.error('Native export verification timed out.'); app.exit(1); }, 15 * 60_000);
app.whenReady().then(async () => {
    server = http.createServer((req, res) => {
        const url = new URL(req.url, origin || 'http://localhost');
        if (url.pathname.startsWith('/api/')) {
            if (req.headers.cookie !== 'fixture_session=owner' || req.headers['x-thingtime-expected-actor'] !== 'owner' ||
                req.headers['x-thingtime-expected-data-plane'] !== 'home' || req.headers['x-thingtime-expected-api-origin'] !== apiOrigin) {
                res.writeHead(401).end('{}'); return;
            }
            if (url.pathname === '/api/v1/auth/me') { accountReads++; res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify({ user: { id: 'owner', accountKind: 'user' } })); return; }
            if (url.pathname === '/api/v1/attachments/content') {
                if (url.searchParams.get('id') !== content.attachmentId || url.searchParams.get('version') !== content.version) { res.writeHead(404).end(); return; }
                if (url.searchParams.has('fingerprint')) { res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify({ ok: true, id: content.attachmentId, ...content })); return; }
                const offset = Number(url.searchParams.get('offset')), length = Number(url.searchParams.get('length')); ranges++;
                assert.ok(length > 0 && length <= 2097152);
                res.writeHead(206, { ETag: `"${content.version}"`, 'Content-Range': `bytes ${offset}-${offset + length - 1}/${bytes.length}`, 'Content-Length': String(length) });
                res.end(bytes.subarray(offset, offset + length)); return;
            }
            res.writeHead(404).end(); return;
        }
        if (url.pathname === '/.well-known/thingtime-capabilities.json') {
            res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify({ schemaVersion: 1, origin: apiOrigin, features: { 'api.attachment-content': { version: '1.14.0' } } })); return;
        }
        res.setHeader('Set-Cookie', 'fixture_session=owner; HttpOnly; SameSite=Strict; Path=/');
        res.setHeader('Content-Type', 'text/html');
        res.end('<!doctype html><title>Thingtime file export verification</title><body style="font:18px system-ui;padding:32px"><h1>Save a retained version</h1><p>This isolated test saves 17 MiB of generated data.</p><p>Choose the suggested destination and click Save version.</p><button id="save">Save this version</button><p id="result"></p><script>save.onclick=async()=>{save.disabled=true;try {const r=await window.thingtimeDesktop.fileExportRequest(' + JSON.stringify({ action: 'save', requestId: randomUUID(), ownerId: 'owner', origin, name: 'Earlier.bin', content }) + '); result.textContent=r.saved?"Saved and verified":"Cancelled";}catch {result.textContent="Save failed";}save.disabled=false;}</script>');
    });
    apiOrigin = await new Promise(resolve => server.listen(0, '127.0.0.1', () => resolve(`http://127.0.0.1:${server.address().port}`)));
    process.env.NODE_ENV = 'production'; process.env.THINGTIME_DESKTOP = '1';
    process.env.THINGTIME_API_FALLBACK_ORIGIN = apiOrigin;
    delete process.env.MONGODB_CONNECTION_STRING; delete process.env.JWT_PRIVATE_KEY; delete process.env.JWT_SECRET;
    renderer = await startRendererServer({ profilePath: path.join(root, 'profile'), loadApplication: async () => {
        const application = await import(pathToFileURL(path.resolve(__dirname, '../../dist/web/.output/server/index.mjs')).href);
        return { ...application, middleware: async (request, response) => {
            if (request.url !== '/') return application.middleware(request, response);
            // Only the generated test UI is synthetic. Every account/content
            // request traverses the packaged Nitro middleware and API proxy.
            const html = await fetch(apiOrigin);
            response.setHeader('Content-Type', 'text/html');
            response.setHeader('Set-Cookie', 'fixture_session=owner; HttpOnly; SameSite=Strict; Path=/');
            response.end(await html.text());
        } };
    } });
    origin = renderer.origin;
    window = new BrowserWindow({ show: !headless, width: 800, height: 540, webPreferences: { preload: path.resolve(__dirname, '../../preload.cjs'), contextIsolation: true, sandbox: true, nodeIntegration: false } });
    host = new DesktopFileExport({ context: () => ({ enabled: true, window, appOrigin: origin, apiOrigin }),
        choose: (parent, options) => headless ? Promise.resolve({ canceled: false, filePath: path.join(output, options.defaultPath) })
            : dialog.showSaveDialog(parent, { ...options, defaultPath: path.join(output, options.defaultPath) }) });
    ipcMain.handle('thingtime-desktop:file-export', async (event, input) => {
        const result = await host.request(event, input);
        if (result.saved) {
            assert.deepEqual(fs.readFileSync(path.join(output, 'Earlier.bin')), bytes);
            assert.deepEqual(fs.readdirSync(output), ['Earlier.bin']); assert.equal(ranges, 9);
            assert.ok(accountReads >= 22);
            console.log(JSON.stringify({ ok: true, bytes: bytes.length, ranges, accountReads, checks: ['production-preload-IPC', 'packaged-Nitro-proxy', 'real-cookie-session', headless ? 'fixture-destination' : 'real-native-save-panel', 'canonical-fingerprint-readback', 'exclusive-publication'], output }));
        }
        return result;
    });
    window.on('closed', () => app.quit());
    await window.loadURL(origin); console.log(JSON.stringify({ ready: true, output }));
    if (headless) {
        const result = await window.webContents.executeJavaScript(`window.thingtimeDesktop.fileExportRequest(${JSON.stringify({
            action: 'save', requestId: randomUUID(), ownerId: 'owner', origin, name: 'Earlier.bin', content
        })})`);
        assert.equal(result.saved, true); app.quit();
    }
}).catch(error => { console.error(error); app.exit(1); });
process.on('SIGTERM', () => app.quit());
app.on('before-quit', () => {
    clearTimeout(timer); host?.invalidate(); server?.close(); void renderer?.close();
    fs.rmSync(root, { recursive: true, force: true });
});
